insert into lessons (id, unit_id, title, intro, visual, sections, sort_order) values
  ('ps-rule', 'en-c1-grammar', 'Present Simple qaydası', 'Present Simple hər gün təkrarlanan işləri bildirir. Gəl qaydanı öyrənək!', null, '[{"heading":"Present Simple nədir?","body":"Hər gün, həmişə və ya adətən təkrarlanan işləri bildirir: I go to school every day. (Mən hər gün məktəbə gedirəm.)"},{"heading":"he / she / it → felə -s","body":"O (he/she/it) ilə felin sonuna -s əlavə olunur: She reads. He plays. Amma I/you/we/they ilə fel dəyişmir: I read, they play."},{"heading":"Sual və inkar: do / does","body":"Sual: Do you like tea? Does she go? İnkar: I don''t eat meat. He doesn''t play. (he/she/it → does/doesn''t.)"}]'::jsonb, 0),
  ('ps-vocab', 'en-c1-vocab', 'Gündəlik fellər (8 söz)', 'Bu gün 8 yeni fel öyrənəcəyik və onları cümlələrdə işlədəcəyik.', null, '[{"heading":"Yeni sözlər (8 fel)","body":"get up — durmaq/qalxmaq · go — getmək · eat — yemək · drink — içmək · read — oxumaq · play — oynamaq · watch — baxmaq · like — sevmək"},{"heading":"Məsləhət","body":"Hər sözü bir cümlədə xatırla: I eat breakfast. She reads a book. Sözü cümlə ilə öyrənmək daha asandır."}]'::jsonb, 0),
  ('ps-listen', 'en-c1-listening', 'Dinlə və seç: cümlələr', 'Cümləni dinlə və düzgün cavabı seç.', null, '[{"heading":"Necə işləyir?","body":"«Dinlə» düyməsinə bas, cümləni eşit və düzgün variantı seç. İstədiyin qədər təkrar dinlə."}]'::jsonb, 0),
  ('ps-read', 'en-c1-reading', 'Reading: My day', 'Qısa mətni oxu və suallara cavab ver.', null, '[{"heading":"Read the text (Mətni oxu)","body":"This is Leyla. She is eleven years old. Every day she gets up at seven o''clock. She eats breakfast and drinks milk. Then she goes to school. At school she reads books and plays with her friends. In the evening she watches TV. She likes her day."},{"heading":"İpucu","body":"Sualı oxu, cavabı mətndə tap. Lazım olsa mətnə yenidən bax."}]'::jsonb, 0),
  ('ps-write', 'en-c1-writing', 'Cümlə qur: Present Simple', 'Sözləri düzgün sıraya düz və Present Simple cümləsi qur.', null, '[{"heading":"Necə işləyir?","body":"Sözlərə sıra ilə bas — cümlə yuxarıda düzələcək. İngilis cümləsi: kim → nə edir → nəyi. he/she ilə felə -s yadında olsun!"}]'::jsonb, 0)
